import{_ as l,l as i,o as e,c as s,v as t,p as n,x as o,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"软烤与溶剂","description":"","frontmatter":{"title":"软烤与溶剂","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/soft-bake.md","filePath":"litho/soft-bake.md","lastUpdated":1789023840000}'),c={name:"litho/soft-bake.md"};function _(f,a,B,E,m,u){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="软烤与溶剂" tabindex="-1">软烤与溶剂 <a class="header-anchor" href="#软烤与溶剂" aria-label="Permalink to &quot;软烤与溶剂&quot;">​</a></h1><div class="epigraph"><p>软烤把旋涂液膜收成可曝光固体：溶剂残留决定扩散、粘附和空洞，温度均匀性决定 CD 的热地图。</p><footer>—— 据 Mack 对 PAB / soft bake 与溶剂残留的论述整理</footer></div><p><a href="/litho/trilayer-soc-sog">上一课</a>把层铺上。缺口是：还是湿的。本课钉软烤（PAB，post-apply bake）：赶溶剂、定自由体积。主干已有 <a href="/litho/pab-solvent">PAB 与溶剂残留</a> 在胶化学补层——若该课已写，本课只补<strong>轨道热板实现</strong>，不重做玻璃化温度。后课显影假定烤完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>溶剂留太多：曝光后酸扩散异常、真空放气、粘附差。烤过头：膜致密、敏感度漂移、甚至提前降解 PAG。径向与片间热不均匀，等价于每场不同 \\(d\\) 和不同动力学。<a href="/litho/hotplate-uniformity">热板均匀性</a> 后课展开地图；本课钉「为什么必须烤」和溶剂的角色。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>热板或接近式烘烤，温度–时间是胶的契约。排气把溶剂带走，避免在膜上再凝。多层分别烤，底层烤温可能高于成像层，以免把上层再溶。残留用称重、FTIR 或厂内代理指标跟，不在本课发明光谱。</p>',7)),(e(),n(p,null,{default:o(()=>[h(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20WET%5B%22%E6%B9%BF%E8%86%9C%22%5D%20--%3E%20BAKE%5B%22%E8%BD%AF%E7%83%A4%22%5D%0A%20%20BAKE%20--%3E%20DRY%5B%22%E5%8F%AF%E6%9B%9D%E5%85%89%E5%9B%BA%E4%BD%93%22%5D%0A%20%20BAKE%20--%3E%20EXH%5B%22%E6%BA%B6%E5%89%82%E6%8E%92%E6%B0%94%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p><span class="marginnote">接近式烤减少颗粒接触，热阻更大，均匀性更依赖气隙控制。接触式热阻小，颗粒风险高。轨道选型是缺陷与 CDU 的权衡。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>溶剂塑化聚合物，自由体积大，PEB 时酸更好走。烤走溶剂，体积收缩，应力可致裂纹——尤其厚 SOC。残留溶剂还改变折射率，轻微移动摆动曲线。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不是 PEB。PEB 在曝光之后，驱动酸扩散，见 <a href="/litho/peb-bake">PEB 温度</a>。下一课显影液如何接触固体膜。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>软烤赶溶剂，把旋涂膜变成曝光对象。</li><li>过与不及都改扩散与光学有效厚度。</li><li>出处：Mack 对 PAB 的论述；轨道热板实践。</li></ul>',7))])}const P=l(c,[["render",_]]);export{b as __pageData,P as default};
